// ─── Helpers ──────────────────────────────────────────────────────

export function getEditionById(id: string): DailyEdition | null {
  return SAMPLE_EDITIONS.find((e) => e.id === id) ?? null;
}

export function getAllEditionIds(): string[] {
  return [...SAMPLE_EDITIONS]
    .sort((a, b) => b.id.localeCompare(a.id))
    .map((e) => e.id);
}

export function getEditionNumber(id: string): number {
  const sorted = [...SAMPLE_EDITIONS].sort((a, b) => a.id.localeCompare(b.id));
  const idx = sorted.findIndex((e) => e.id === id);
  return idx >= 0 ? idx + 1 : 0;
}
